          params: [['folderId', 'path', 'string', true, 'Папка'], ['limit', 'query', 'int', false, 'До 100, по умолчанию 50'], ['cursor', 'query', 'string', false, 'email_id последнего письма прошлой страницы'], ['unread', 'query', 'bool', false, 'Только непрочитанные']],
