    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, peak = p.peak || 1, wave = p.wave || 1, spam = i.spam / 100;
      const U = i.users * growth, mix = 1 - spam + spam * wave;
      const send = (U * i.send) / 86400, recvBase = (U * i.recv) / 86400, inbound = recvBase * mix;
      const reads = (U * i.reads) / 86400, search = reads * 0.05, att = (send * i.att) / 100 + reads * 0.02;
      const conns = (U * i.online) / 100, ws = conns / 60;
      return {
        U, send, recvBase, inbound, reads, search, att, conns, ws, k: peak, peak, wave, growth, spam,
        push: (recvBase * (1 - spam) * i.online) / 100, attIn: (recvBase * (1 - spam) * i.att) / 100,
        metaPB: (U * i.recv * 50e3 * 365) / 1e15, attPB: (U * i.recv * 365 * (i.att / 100) * i.attSize * 1e3) / 1e15,
        Sday: U * i.send, Rday: U * i.recv * mix, spamDay: U * i.recv * spam * wave,
      };
    },

